window.US_PRESIDENT_DECKS = [{"id":"us-presidents-all","name":"U.S. Presidents","shortName":"Presidents","builtIn":true,"sourceTitle":"White House presidential history and standard historical references","sourceUrl":"https://www.whitehouse.gov/history/","cards":[{"id":"us-president-1","front":"George Washington","back":"Term: 1789–1797\n\nSignificant events and actions: Established major presidential precedents; supported Hamilton’s financial program; proclaimed neutrality in European wars; oversaw the response to the Whiskey Rebellion.","frontImage":"./assets/us-presidents/george-washington.jpg","number":"1st","party":"Unaffiliated"},{"id":"us-president-2","front":"John Adams","back":"Term: 1797–1801\n\nSignificant events and actions: Avoided full war with France after the XYZ Affair; signed the Alien and Sedition Acts; appointed John Marshall chief justice.","frontImage":"./assets/us-presidents/john-adams.jpg","number":"2nd","party":"Federalist"},{"id":"us-president-3","front":"Thomas Jefferson","back":"Term: 1801–1809\n\nSignificant events and actions: Completed the Louisiana Purchase; sponsored the Lewis and Clark expedition; imposed the Embargo Act; reduced some federal taxes and military spending.","frontImage":"./assets/us-presidents/thomas-jefferson.jpg","number":"3rd","party":"Democratic-Republican"},{"id":"us-president-4","front":"James Madison","back":"Term: 1809–1817\n\nSignificant events and actions: Led the nation through the War of 1812; oversaw the burning of Washington and the Treaty of Ghent; supported the Second Bank of the United States.","frontImage":"./assets/us-presidents/james-madison.jpg","number":"4th","party":"Democratic-Republican"},{"id":"us-president-5","front":"James Monroe","back":"Term: 1817–1825\n\nSignificant events and actions: Presided over the Era of Good Feelings; issued the Monroe Doctrine; acquired Florida; signed the Missouri Compromise.","frontImage":"./assets/us-presidents/james-monroe.jpg","number":"5th","party":"Democratic-Republican"},{"id":"us-president-6","front":"John Quincy Adams","back":"Term: 1825–1829\n\nSignificant events and actions: Promoted federal support for roads, canals, science, and education; faced opposition after the disputed 1824 election and “corrupt bargain” charge.","frontImage":"./assets/us-presidents/john-quincy-adams.jpg","number":"6th","party":"Democratic-Republican"},{"id":"us-president-7","front":"Andrew Jackson","back":"Term: 1829–1837\n\nSignificant events and actions: Expanded presidential power; fought the Bank of the United States; enforced Indian removal; confronted nullification; used the spoils system.","frontImage":"./assets/us-presidents/andrew-jackson.jpg","number":"7th","party":"Democratic"},{"id":"us-president-8","front":"Martin Van Buren","back":"Term: 1837–1841\n\nSignificant events and actions: Faced the Panic of 1837 and a prolonged depression; created the Independent Treasury; continued federal Indian removal policy.","frontImage":"./assets/us-presidents/martin-van-buren.jpg","number":"8th","party":"Democratic"},{"id":"us-president-9","front":"William Henry Harrison","back":"Term: March 4–April 4, 1841\n\nSignificant events and actions: Delivered the longest inaugural address; died after 31 days, the shortest presidency, creating uncertainty about presidential succession.","frontImage":"./assets/us-presidents/william-henry-harrison.jpg","number":"9th","party":"Whig"},{"id":"us-president-10","front":"John Tyler","back":"Term: 1841–1845\n\nSignificant events and actions: Established that a vice president fully becomes president after a president dies; vetoed Whig banking bills; supported the annexation of Texas.","frontImage":"./assets/us-presidents/john-tyler.jpg","number":"10th","party":"Whig, then unaffiliated"},{"id":"us-president-11","front":"James K. Polk","back":"Term: 1845–1849\n\nSignificant events and actions: Led the United States in the Mexican–American War; settled the Oregon boundary; greatly expanded U.S. territory; lowered tariffs and restored the Independent Treasury.","frontImage":"./assets/us-presidents/james-k-polk.jpg","number":"11th","party":"Democratic"},{"id":"us-president-12","front":"Zachary Taylor","back":"Term: 1849–1850\n\nSignificant events and actions: Opposed extending slavery into territories gained from Mexico; encouraged California statehood; died in office before the Compromise of 1850.","frontImage":"./assets/us-presidents/zachary-taylor.jpg","number":"12th","party":"Whig"},{"id":"us-president-13","front":"Millard Fillmore","back":"Term: 1850–1853\n\nSignificant events and actions: Signed the Compromise of 1850, including the Fugitive Slave Act; supported opening trade with Japan through the Perry expedition.","frontImage":"./assets/us-presidents/millard-fillmore.jpg","number":"13th","party":"Whig"},{"id":"us-president-14","front":"Franklin Pierce","back":"Term: 1853–1857\n\nSignificant events and actions: Signed the Kansas–Nebraska Act; violence in “Bleeding Kansas” intensified sectional conflict; supported expansionist diplomacy including the Gadsden Purchase.","frontImage":"./assets/us-presidents/franklin-pierce.jpg","number":"14th","party":"Democratic"},{"id":"us-president-15","front":"James Buchanan","back":"Term: 1857–1861\n\nSignificant events and actions: Backed the proslavery Lecompton Constitution; failed to halt the secession crisis; his administration was marked by the Dred Scott decision and sectional collapse.","frontImage":"./assets/us-presidents/james-buchanan.jpg","number":"15th","party":"Democratic"},{"id":"us-president-16","front":"Abraham Lincoln","back":"Term: 1861–1865\n\nSignificant events and actions: Led the Union through the Civil War; issued the Emancipation Proclamation; supported the Thirteenth Amendment; expanded federal wartime power; was assassinated.","frontImage":"./assets/us-presidents/abraham-lincoln.jpg","number":"16th","party":"Republican"},{"id":"us-president-17","front":"Andrew Johnson","back":"Term: 1865–1869\n\nSignificant events and actions: Clashed with Congress over Reconstruction; vetoed civil-rights legislation; was impeached after violating the Tenure of Office Act and acquitted by one Senate vote.","frontImage":"./assets/us-presidents/andrew-johnson.jpg","number":"17th","party":"National Union / Democratic"},{"id":"us-president-18","front":"Ulysses S. Grant","back":"Term: 1869–1877\n\nSignificant events and actions: Enforced Reconstruction and fought the Ku Klux Klan; supported the Fifteenth Amendment; pursued Native American “Peace Policy”; his administration suffered major scandals.","frontImage":"./assets/us-presidents/ulysses-s-grant.jpg","number":"18th","party":"Republican"},{"id":"us-president-19","front":"Rutherford B. Hayes","back":"Term: 1877–1881\n\nSignificant events and actions: Took office after the disputed 1876 election and Compromise of 1877; withdrew remaining federal troops from the South; promoted civil-service reform.","frontImage":"./assets/us-presidents/rutherford-b-hayes.jpg","number":"19th","party":"Republican"},{"id":"us-president-20","front":"James A. Garfield","back":"Term: March 4–September 19, 1881\n\nSignificant events and actions: Supported civil-service reform and Black voting rights; was assassinated after only months in office, helping build support for the Pendleton Act.","frontImage":"./assets/us-presidents/james-a-garfield.jpg","number":"20th","party":"Republican"},{"id":"us-president-21","front":"Chester A. Arthur","back":"Term: 1881–1885\n\nSignificant events and actions: Signed the Pendleton Civil Service Reform Act; modernized the Navy; signed the Chinese Exclusion Act after vetoing a longer version.","frontImage":"./assets/us-presidents/chester-a-arthur.jpg","number":"21st","party":"Republican"},{"id":"us-president-22","front":"Grover Cleveland","back":"Term: 1885–1889; 1893–1897\n\nSignificant events and actions: Only president before Trump to serve nonconsecutive terms; pursued tariff reduction and limited government; faced the Pullman Strike and Panic of 1893.","frontImage":"./assets/us-presidents/grover-cleveland.jpg","number":"22nd and 24th","party":"Democratic"},{"id":"us-president-23","front":"Benjamin Harrison","back":"Term: 1889–1893\n\nSignificant events and actions: Signed the Sherman Antitrust Act and McKinley Tariff; admitted six western states; supported federal protection of Black voting rights.","frontImage":"./assets/us-presidents/benjamin-harrison.jpg","number":"23rd","party":"Republican"},{"id":"us-president-24","front":"William McKinley","back":"Term: 1897–1901\n\nSignificant events and actions: Led the nation through the Spanish–American War; annexed Hawaii; acquired overseas territories; was assassinated early in his second term.","frontImage":"./assets/us-presidents/william-mckinley.jpg","number":"25th","party":"Republican"},{"id":"us-president-25","front":"Theodore Roosevelt","back":"Term: 1901–1909\n\nSignificant events and actions: Advanced the Square Deal; regulated corporations; expanded conservation; backed the Panama Canal; asserted U.S. power through the Roosevelt Corollary.","frontImage":"./assets/us-presidents/theodore-roosevelt.jpg","number":"26th","party":"Republican"},{"id":"us-president-26","front":"William Howard Taft","back":"Term: 1909–1913\n\nSignificant events and actions: Pursued antitrust cases; promoted Dollar Diplomacy; supported the Sixteenth Amendment; later became chief justice of the United States.","frontImage":"./assets/us-presidents/william-howard-taft.jpg","number":"27th","party":"Republican"},{"id":"us-president-27","front":"Woodrow Wilson","back":"Term: 1913–1921\n\nSignificant events and actions: Created the Federal Reserve and Federal Trade Commission; led the United States in World War I; proposed the Fourteen Points and League of Nations; presided over federal segregation and wartime repression.","frontImage":"./assets/us-presidents/woodrow-wilson.jpg","number":"28th","party":"Democratic"},{"id":"us-president-28","front":"Warren G. Harding","back":"Term: 1921–1923\n\nSignificant events and actions: Promoted a “return to normalcy”; signed the Budget and Accounting Act; his administration became associated with Teapot Dome and other scandals.","frontImage":"./assets/us-presidents/warren-g-harding.jpg","number":"29th","party":"Republican"},{"id":"us-president-29","front":"Calvin Coolidge","back":"Term: 1923–1929\n\nSignificant events and actions: Favored limited government, tax cuts, and business growth; signed the Immigration Act of 1924; declined major federal relief for struggling farmers.","frontImage":"./assets/us-presidents/calvin-coolidge.jpg","number":"30th","party":"Republican"},{"id":"us-president-30","front":"Herbert Hoover","back":"Term: 1929–1933\n\nSignificant events and actions: The Great Depression began during his presidency; supported voluntary and limited federal responses, the Reconstruction Finance Corporation, and the Smoot–Hawley Tariff; ordered removal of the Bonus Army camp.","frontImage":"./assets/us-presidents/herbert-hoover.jpg","number":"31st","party":"Republican"},{"id":"us-president-31","front":"Franklin D. Roosevelt","back":"Term: 1933–1945\n\nSignificant events and actions: Launched the New Deal; reshaped the federal government; led the nation through most of World War II; signed Executive Order 9066 authorizing Japanese American incarceration; served four terms.","frontImage":"./assets/us-presidents/franklin-d-roosevelt.jpg","number":"32nd","party":"Democratic"},{"id":"us-president-32","front":"Harry S. Truman","back":"Term: 1945–1953\n\nSignificant events and actions: Authorized atomic bombings of Japan; announced the Truman Doctrine and Marshall Plan; recognized Israel; desegregated the armed forces; led during the Korean War.","frontImage":"./assets/us-presidents/harry-s-truman.jpg","number":"33rd","party":"Democratic"},{"id":"us-president-33","front":"Dwight D. Eisenhower","back":"Term: 1953–1961\n\nSignificant events and actions: Ended active U.S. participation in the Korean War; created the Interstate Highway System; enforced school desegregation in Little Rock; warned about the military-industrial complex.","frontImage":"./assets/us-presidents/dwight-d-eisenhower.jpg","number":"34th","party":"Republican"},{"id":"us-president-34","front":"John F. Kennedy","back":"Term: 1961–1963\n\nSignificant events and actions: Managed the Cuban Missile Crisis; launched the Peace Corps; backed the space program; faced the Bay of Pigs and expanding Vietnam involvement; was assassinated.","frontImage":"./assets/us-presidents/john-f-kennedy.jpg","number":"35th","party":"Democratic"},{"id":"us-president-35","front":"Lyndon B. Johnson","back":"Term: 1963–1969\n\nSignificant events and actions: Won passage of major civil-rights laws; created Medicare and Medicaid through the Great Society; escalated U.S. involvement in Vietnam.","frontImage":"./assets/us-presidents/lyndon-b-johnson.jpg","number":"36th","party":"Democratic"},{"id":"us-president-36","front":"Richard Nixon","back":"Term: 1969–1974\n\nSignificant events and actions: Opened relations with China; pursued détente with the Soviet Union; created the EPA; expanded and later reduced U.S. involvement in Vietnam; resigned over Watergate.","frontImage":"./assets/us-presidents/richard-nixon.jpg","number":"37th","party":"Republican"},{"id":"us-president-37","front":"Gerald Ford","back":"Term: 1974–1977\n\nSignificant events and actions: Pardoned Richard Nixon; signed the Helsinki Accords; faced inflation, recession, and the final U.S. withdrawal from Vietnam.","frontImage":"./assets/us-presidents/gerald-ford.jpg","number":"38th","party":"Republican"},{"id":"us-president-38","front":"Jimmy Carter","back":"Term: 1977–1981\n\nSignificant events and actions: Brokered the Camp David Accords; established the Departments of Energy and Education; emphasized human rights; faced the Iran hostage crisis and energy problems.","frontImage":"./assets/us-presidents/jimmy-carter.jpg","number":"39th","party":"Democratic"},{"id":"us-president-39","front":"Ronald Reagan","back":"Term: 1981–1989\n\nSignificant events and actions: Advanced tax cuts, deregulation, and higher defense spending; confronted the Soviet Union before later arms-control agreements; appointed conservative judges; faced the Iran–Contra affair.","frontImage":"./assets/us-presidents/ronald-reagan.jpg","number":"40th","party":"Republican"},{"id":"us-president-40","front":"George H. W. Bush","back":"Term: 1989–1993\n\nSignificant events and actions: Led the coalition in the Persian Gulf War; managed the end of the Cold War; signed the Americans with Disabilities Act; broke his “no new taxes” pledge.","frontImage":"./assets/us-presidents/george-h-w-bush.jpg","number":"41st","party":"Republican"},{"id":"us-president-41","front":"Bill Clinton","back":"Term: 1993–2001\n\nSignificant events and actions: Signed NAFTA and welfare reform; presided over economic growth and budget surpluses; intervened in the Balkans; was impeached and acquitted.","frontImage":"./assets/us-presidents/bill-clinton.jpg","number":"42nd","party":"Democratic"},{"id":"us-president-42","front":"George W. Bush","back":"Term: 2001–2009\n\nSignificant events and actions: Responded to the September 11 attacks; launched wars in Afghanistan and Iraq; signed the PATRIOT Act and No Child Left Behind; faced Hurricane Katrina and the 2008 financial crisis.","frontImage":"./assets/us-presidents/george-w-bush.jpg","number":"43rd","party":"Republican"},{"id":"us-president-43","front":"Barack Obama","back":"Term: 2009–2017\n\nSignificant events and actions: Signed the Affordable Care Act and economic stimulus; oversaw the operation that killed Osama bin Laden; supported the Paris climate agreement; was the first African American president.","frontImage":"./assets/us-presidents/barack-obama.jpg","number":"44th","party":"Democratic"},{"id":"us-president-44","front":"Donald Trump","back":"Term: 2017–2021; 2025–present\n\nSignificant events and actions: Signed major tax cuts; appointed three Supreme Court justices; pursued restrictive immigration and tariff policies; was impeached twice and acquitted twice; returned for a nonconsecutive second presidency.","frontImage":"./assets/us-presidents/donald-trump.jpg","number":"45th and 47th","party":"Republican"},{"id":"us-president-45","front":"Joe Biden","back":"Term: 2021–2025\n\nSignificant events and actions: Signed major pandemic relief, infrastructure, climate, and semiconductor legislation; supported Ukraine after Russia’s invasion; ended the U.S. military presence in Afghanistan; appointed Ketanji Brown Jackson to the Supreme Court.","frontImage":"./assets/us-presidents/joe-biden.jpg","number":"46th","party":"Democratic"}],"questions":[],"feynmanPrompts":[]}];
